export const PREDICATE_NAMES = Object.freeze(Object.keys(PREDICATES));

/** Entity kinds used by `entity.kind`. */
export const ENTITY_KINDS = Object.freeze([
	"self",
	"person",
	"org",
	"project",
	"place",
	"device",
	"account",
	"other",
]);

/**
 * Look up a predicate definition.
 * @param {string} name - predicate name.
 * @returns {typeof PREDICATES[string] | null} definition or null.
 */
export function predicateSpec(name) {
	return Object.prototype.hasOwnProperty.call(PREDICATES, name) ? PREDICATES[name] : null;
}

/**
 * One-line list for error messages and the tool description.
 * @returns {string} comma-separated names.
 */
export function predicateList() {
	return PREDICATE_NAMES.join(", ");
}

/**
 * Describe the vocabulary compactly for the model-facing tool description.
 * Kept short on purpose; `describeCatalog()` is the full version.
 * @returns {string} multi-line list with kind/cardinality/pinned markers.
 */
export function describePredicates() {
	return PREDICATE_NAMES.map((name) => {
		const spec = PREDICATES[name];
		const flags = [spec.kind, spec.cardinality, spec.pinned ? "pinned" : ""]
			.filter((part) => part.length > 0)
			.join("/");
		return `${name} (${flags})`;
	}).join("; ");
}

/**
 * Full catalog for the `describe` action and code that needs the metadata.
 * @returns {Array<{name: string, kind: string, cardinality: string, pinned: boolean, about: string, synonyms: string[], examples: string[]}>} catalog.
 */
export function predicateCatalog() {
	return PREDICATE_NAMES.map((name) => {
		const spec = PREDICATES[name];
		return {
			name,
			kind: spec.kind,
			cardinality: spec.cardinality,
			pinned: spec.pinned,
			about: spec.about,
			synonyms: [...spec.synonyms],
			examples: [...spec.examples],
		};
	});
}

/**
 * Human/model-readable full catalog. One predicate per line so the tool
 * output stays scannable on a phone.
 * @returns {string} multi-line catalog.
 */
export function describeCatalog() {
	return predicateCatalog()
		.map((spec) => {
			const flags = `${spec.kind}/${spec.cardinality}${spec.pinned ? "/pinned" : ""}`;
			const synonyms = spec.synonyms.length > 0 ? ` synonyms: ${spec.synonyms.join(", ")}` : "";
			const examples = spec.examples.length > 0 ? ` examples: ${spec.examples.join(", ")}` : "";
			return `${spec.name} (${flags}) — ${spec.about}${synonyms}.${examples}`;
		})
		.join("\n");
}

/**
 * Normalize text for synonym and fuzzy matching.
 * @param {string} value - raw text.
 * @returns {string} lowercase, no spaces/underscores/hyphens.
 */
function normalize(value) {
	return String(value ?? "").toLowerCase().replaceAll(/[\s_-]+/g, "");
}

/**
 * Predicates whose name or synonym appears in a natural-language query.
 * Used by `search` so "我对什么过敏" still finds the `allergy` rows.
 * @param {string} text - query.
 * @returns {string[]} matching predicate names.
 */
export function predicatesMatching(text) {
	const needle = normalize(text);
	if (needle.length === 0) return [];
	const hits = new Set();
	for (const name of PREDICATE_NAMES) {
		const spec = PREDICATES[name];
		const terms = [name, ...spec.synonyms];
		for (const term of terms) {
			const normalized = normalize(term);
			if (normalized.length < 2) continue;
			if (needle.includes(normalized) || normalized.includes(needle)) {
				hits.add(name);
				break;
			}
		}
	}
	return [...hits];
}

/**
 * Levenshtein distance, bounded to short vocabulary terms.
 * @param {string} a - first string.
 * @param {string} b - second string.
 * @returns {number} edit distance.
 */
function distance(a, b) {
	const rows = a.length + 1;
	const cols = b.length + 1;
	let previous = Array.from({ length: cols }, (_, index) => index);
	for (let row = 1; row < rows; row++) {
		const current = [row];
		for (let col = 1; col < cols; col++) {
			const cost = a[row - 1] === b[col - 1] ? 0 : 1;
			current[col] = Math.min(
				previous[col] + 1,
				current[col - 1] + 1,
				previous[col - 1] + cost,
			);
		}
		previous = current;
	}
	return previous[cols - 1];
}

/**
 * Closest predicates for an unknown name, used in the error path.
 * @param {string} text - the rejected predicate.
 * @param {number} [limit] - maximum suggestions.
 * @returns {string[]} up to `limit` names, or an empty list.
 */
export function suggestPredicate(text, limit = 3) {
	const needle = normalize(text);
	if (needle.length === 0) return [];
	const scored = PREDICATE_NAMES.map((name) => {
		const spec = PREDICATES[name];
		const best = [name, ...spec.synonyms].reduce(
			(minimum, term) => Math.min(minimum, distance(needle, normalize(term))),
			Number.POSITIVE_INFINITY,
		);
		return { name, distance: best };
	}).sort((left, right) => left.distance - right.distance || left.name.localeCompare(right.name));
	const cutoff = Math.max(2, Math.floor(needle.length / 3));
	return scored.filter((entry) => entry.distance <= cutoff).slice(0, limit).map((entry) => entry.name);
}
